import{_ as t,c as e,o,ae as l}from"./chunks/framework.Bi6zybwU.js";const d=JSON.parse('{"title":"Row and Column Calculation","description":"Row and Column Calculation","frontmatter":{"title":"Row and Column Calculation","description":"Row and Column Calculation"},"headers":[],"relativePath":"guide/table-management/row-column-data-calculation.md","filePath":"guide/table-management/row-column-data-calculation.md"}'),n={name:"guide/table-management/row-column-data-calculation.md"};function i(u,a,c,s,r,m){return o(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="row-and-column-calculation" tabindex="-1">Row and Column Calculation <a class="header-anchor" href="#row-and-column-calculation" aria-label="Permalink to &quot;Row and Column Calculation&quot;">​</a></h1><p>Row / Column Calculation is a feature that many Ninja Tables plugin users would like to implement in their tables. Calculate tabular data in a numeric table easily in this table plugin. You may perform data calculation in Ninja Tables just by following a few easy steps. We have 2 different methods for row data calculation and column data calculation.</p><h2 id="calculate-tabular-data-in-rows-columns" tabindex="-1">Calculate Tabular Data in Rows/Columns <a class="header-anchor" href="#calculate-tabular-data-in-rows-columns" aria-label="Permalink to &quot;Calculate Tabular Data in Rows/Columns&quot;">​</a></h2><p>Follow this simple guide to discover how to calculate data in table rows and columns. Suppose we have a table that contains 3 numeric data columns- Number One, Number Two, and Number Three. <img src="https://ninjatables.com/wp-content/uploads/2022/09/01-5-scaled.webp" alt=""></p><h3 id="row-calculation" tabindex="-1">Row Calculation <a class="header-anchor" href="#row-calculation" aria-label="Permalink to &quot;Row Calculation&quot;">​</a></h3><p>We have another column named **Result **that will display the calculated results of all the numbers in a row.</p><ul><li>If you want to calculate the sum of a row containing numeric data, navigate to the **Table Configuration **-&gt;&gt; <strong>Transform Value</strong>.</li><li>Here you need to add a shortcode to find the sum of the rows. Ninja Tables has a feature to <strong>&quot;Enable Excel Formula support for Transform Value</strong>.&quot; Enable this option to get the Excel summation formula.</li><li>This is a basic single-line shortcode: <code>=SUM(&amp;#123;&amp;#123;Column 1&amp;#125;&amp;#125;+&amp;#123;&amp;#123;Column 2&amp;#125;&amp;#125;+&amp;#123;&amp;#123;Column 3&amp;#125;&amp;#125;)</code>. Inside the curly brackets place the **Shortcode Value **off all three columns. To learn more about this feature, read this <a href="https://ninjatables.com/docs/transform-value/" target="_blank" rel="noreferrer">documentation</a>.</li><li>So the final code would look like this: <code>=SUM( &amp;#123;&amp;#123;row.numberone&amp;#125;&amp;#125; + &amp;#123;&amp;#123;row.numbertwo&amp;#125;&amp;#125; + &amp;#123;&amp;#123;row.numberthree&amp;#125;&amp;#125;)</code>.</li><li>Then click on the **Update **button to save the code. In the preview mode, the **Result **column of the table will now display the sum of the rows. Like the example given below - <img src="https://ninjatables.com/wp-content/uploads/2023/01/row-column-calculation-3.png" alt="Result"></li></ul><h3 id="column-calculation" tabindex="-1">Column Calculation <a class="header-anchor" href="#column-calculation" aria-label="Permalink to &quot;Column Calculation&quot;">​</a></h3><p>Calculating column data is different.</p><ul><li>First, go to this GitHub <a href="https://gist.github.com/reachkamrul/11e6e60d4aa113abe81586367cc27b77" target="_blank" rel="noreferrer">link</a> to get the JS code. Copy the code.</li><li>Now go to the **Custom CSS/JS **tab &amp; click on the **Custom Javascript **button. Paste the code that you copied and hit the save button.</li><li>If you wish to calculate the total sum of all the numbers in the 1st column, you need to give the **Column key **of that specific column, on the first line of the code, which is <code>var myClasses=&quot;&quot;</code></li><li>If you want to show the results of one single column, you need to put the key to that column only. If you want to apply calculations to multiple columns, put their columns key by using commas in between each column key. <img src="https://ninjatables.com/wp-content/uploads/2022/09/03-4-scaled.webp" alt="Example: using three column"></li><li>After that, click on the **Save Custom Javascript **button to save the code.</li><li>When you click on the preview mode, all three columns will display the sum at the bottom. See the example given below. <img src="https://ninjatables.com/wp-content/uploads/2023/01/row-column-calculation-6.png" alt="Preview"> This is how we can <strong>calculate rows and columns</strong> in Ninja Tables by following some easy steps!</li></ul>',10)])])}const p=t(n,[["render",i]]);export{d as __pageData,p as default};
